import com.bridger.momentum.*;
import java.util.*;

public final class FailureAnalysisRegression {
    private static void check(boolean b,String why){if(!b)throw new AssertionError(why);}
    public static void main(String[] args){List<ReplayData.Frame> frames=new ArrayList<>();for(int i=0;i<20;i++){ReplayData.TickStats stats=new ReplayData.TickStats(0,0,0,0,i==10||i==14||i==16||i==19?1:0,0,0,0,0,0,-.2,0);frames.add(new ReplayData.Frame(i*.2,70-i*.1,i*.03,0,0,0,0,false,false,0,0,0,24,0,stats));}ReplayData data=new ReplayData(frames,Arrays.asList(new ReplayData.Block(1,69,0,24,0,12,true)),false);List<ReplayFailureAnalysis.Finding> findings=ReplayFailureAnalysis.analyze("FAILED","X",data);check(findings.stream().anyMatch(f->f.tick==14&&f.text.contains("no placement")),"Missing-placement observation absent");check(findings.stream().noneMatch(f->f.tick==10&&f.text.contains("no placement")),"Delayed confirmed placement was called missing");check(findings.stream().noneMatch(f->f.tick==19&&f.text.contains("no placement")),"Incomplete tail falsely implied a missing placement");check(findings.stream().noneMatch(f->f.tick==16&&f.text.contains("no placement")),"Tick-boundary endpoint was counted as a fully observed future tick");check(findings.stream().anyMatch(f->f.text.contains("Descended"))&&findings.stream().anyMatch(f->f.text.contains("sideways")),"Recorded ending motion was ignored");check(ReplayFailureAnalysis.analyze("SUCCESS","X",data).size()==1,"Successful run was diagnosed as a fail");check(ReplayFailureAnalysis.analyze("FAILED","X",null).get(0).text.contains("statistics alone"),"Missing recording invented evidence");System.out.println("PASS: evidence-only fail analysis, delayed placements, incomplete tails and missing data");}
}
